"""Read-only final R1 state/provenance receipt; no activation/import side effects."""
from pathlib import Path
import importlib.util,json
r=Path('/opt/vps/apps/al-rifai');spec=importlib.util.spec_from_file_location('repair',r/'scripts/workflow-repair-production.py');repair=importlib.util.module_from_spec(spec);spec.loader.exec_module(repair)
result={'status':'NOT_ACCEPTED','database':repair.database_state(),'runtime':repair.runtime()}
result['provenance']=json.loads(repair.pg("""BEGIN READ ONLY;
SELECT jsonb_build_object('programs',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'revision',revision,'state',status,'authority',details::jsonb->'programCommand'->>'authority','events',jsonb_array_length(details::jsonb->'programCommand'->'events'))),'[]'::jsonb) FROM public.programs),'links',(SELECT coalesce(jsonb_agg(jsonb_build_object('eventId',l.event_id,'operationId',l.operation_id,'sourceRef',l.source_ref,'programId',l.program_id,'outcome',l.outcome,'reasons',l.reasons,'sourceTime',s.source_time,'role',e.assertion->'admission'->>'role','historicalAuthority',e.assertion->'admission'->'historical','bindingRefs',e.assertion->'admission'->'bindingRefs','direction',e.assertion->>'direction')),'[]'::jsonb) FROM public.roster_source_links l JOIN public.source_refs s ON s.id=l.source_ref JOIN public.domain_events e ON e.id=l.event_id),'assignments',(SELECT count(*) FROM public.program_assignments),'cashStates',(SELECT jsonb_agg(x) FROM (SELECT state,count(*) AS count FROM public.cash_instructions GROUP BY state) x),'versions',(SELECT jsonb_agg(x) FROM (SELECT assertion->>'version' AS version,count(*) AS count FROM public.domain_events WHERE resource_kind='WHATSAPP_EXTRACTION' GROUP BY assertion->>'version') x),'sameAmountDifferentOperations',(SELECT count(*) FROM (SELECT employee_mobile,amount_minor FROM public.cash_instructions GROUP BY employee_mobile,amount_minor HAVING count(DISTINCT operation_id)>1) x),'duplicateOperations',(SELECT count(*) FROM (SELECT operation_id FROM public.cash_instructions GROUP BY operation_id HAVING count(*)>1) x));
ROLLBACK;"""))
before=json.loads((r/'data/workflow-r1-repair-result.json').read_text())['before'];result['invariants']={'postgresAndWhatsAppUnchanged':all(result['runtime'][n]==before['runtime'][n] for n in repair.NAMES[1:]),'financialOff':result['runtime'][repair.NAMES[0]]['financialOff'],'sameCandidateImage':result['runtime'][repair.NAMES[0]]['image']==repair.CANDIDATE,'allOriginalCashInstructionsUnchanged':result['database']['cashDigest']==before['database']['cashDigest'],'financialRowsZero':result['database']['counts']['postings']==result['database']['counts']['movements']==0,'guardUnchanged':result['database']['guard']==before['database']['guard'],'programHistoryTriggerUnchanged':result['database']['historyTrigger']==before['database']['historyTrigger'] and result['database']['historyTriggerEnabled'],'ledger0012ChecksumPreserved':next(x for x in result['database']['ledger'] if x['id']=='0012_business_workflows.sql')['sha256']==repair.HASH0012}
assert all(result['invariants'].values()),'R1_STATE_INVARIANT_FAILED'
result['confirmedPrograms']=sum(p['state']=='Confirmed' for p in result['provenance']['programs']);result['historicallyAuthorizedConfirmations']=sum(l['outcome']=='CONFIRMED' and l['historicalAuthority'] is True and l['role']=='ADMIN' for l in result['provenance']['links'])
(r/'data/workflow-r1-current-state.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'status':result['status'],'ledgerEntries':len(result['database']['ledger']),'counts':result['database']['counts'],'confirmedPrograms':result['confirmedPrograms'],'historicallyAuthorizedConfirmations':result['historicallyAuthorizedConfirmations'],'invariants':result['invariants'],'linkOutcomes':[{k:l[k] for k in ('outcome','reasons','role','historicalAuthority')} for l in result['provenance']['links']]}))
